```
/*eslint no-empty-pattern: ["error", { "allowObjectPatternsAsParameters": true }]*/
function foo({a: }) {}
const bar = function({a: }) {};
const qux = ({a: }) => {};
const quux = ( = bar) => {};
const item = ( = { bar: 1 }) => {};
function baz() {}
