Source: Rust Nomicon > Splitting Borrows

fn main() {}
use std::collections::VecDeque;
type Link<T> = Option<Box<Node<T>>>;
struct Node<T> {
 elem: T,
 left: Link<T>,
 right: Link<T>,
}
pub struct Tree<T> {
 root: Link<T>,
}
struct NodeIterMut<'a, T: 'a> {
 elem: Option<&'a mut T>,
 left: Option<&'a mut Node<T>>,
 right: Option<&'a mut Node<T>>,
}
enum State<'a, T: 'a> {
 Elem(&'a mut T),
 Node(&'a mut Node<T>),
}
pub struct IterMut<'a, T: 'a>(VecDeque<NodeIterMut<'a, T>>);
impl<T> Tree<T> {
 pub fn iter_mut(&mut self) -> IterMut<T> {
 let mut deque = VecDeque::new();
 if let Some(root) = self.root.as_mut() {
 deque.push_front(root.iter_mut());
 }
 IterMut(deque)
 }
}
impl<T> Node<T> {
 pub fn iter_mut(&mut self) -> NodeIterMut<T> {
 NodeIterMut {
 elem: Some(&mut self.elem),
 left: self.left.as_deref_mut(),
 right: self.right.as_deref_mut(),
 }
 }
}
impl<'a, T> Iterator for NodeIterMut<'a, T> {
 type Item = State<'a, T>;
 fn next(&mut self) -> Option<Self::Item> {
 self.left.take().map(State::Node).or_else(|| {
 self.elem
 .take()
 .map(State::Elem)
 .or_else(|| self.right.take().map(State::Node))
 })
 }
}
impl<'a, T> DoubleEndedIterator for NodeIterMut<'a, T> {
 fn next_back(&mut self) -> Option<Self::Item> {
 self.right.take().map(State::Node).or_else(|| {
 self.elem
 .take()
 .map(State::Elem)
 .or_else(|| self.left.take().map(State::Node))
 })
 }
}
impl<'a, T> Iterator for IterMut<'a, T> {
 type Item = &'a mut T;
 fn next(&mut self) -> Option<Self::Item> {
 loop {
 match self.0.front_mut().and_then(Iterator::next) {
 Some(State::Elem(elem)) => return Some(elem),
 Some(State::Node(node)) => self.0.push_front(node.iter_mut()),
 None => {
 self.0.pop_front()?;
 }
 }
 }
 }
}
impl<'a, T> DoubleEndedIterator for IterMut<'a, T> {
 fn next_back(&mut self) -> Option<Self::Item> {
 loop {
 match self.0.back_mut().and_then(DoubleEndedIterator::next_back) {
 Some(State::Elem(elem)) => return Some(elem),
 Some(State::Node(node)) => self.0.push_back(node.iter_mut()),
 None => {
 self.0.pop_back()?;
 }
 }
 }
 }
}
```
All of these are completely safe and work on stable Rust! This ultimately falls out of the simple struct case we saw before: Rust understands that you can safely split a mutable reference into subfields. We can then encode permanently consuming a reference via Options (or in the case of slices, replacing with an empty slice).

