#![warn(clippy::foo_functions)] // < Add this, so the lint is guaranteed to be enabled in this file
// Impl methods
struct A;
impl A {
 pub fn fo(&self) {}
 pub fn foo(&self) {}
 //~^ foo_functions
 pub fn food(&self) {}
}
// Default trait methods
trait B {
 fn fo(&self) {}
